select 'fact_orders' t, count(*) n from dwh.fact_orders union all select 'fact_order_items', count(*) from dwh.fact_order_items union all select 'fact_payments', count(*) from dwh.fact_payments union all select 'fact_shipments', count(*) from dwh.fact_shipments union all select 'fact_returns', count(*) from dwh.fact_returns union all select 'dim_customer', count(*) from dwh.dim_customer union all select 'dim_customer_current', count(*) from dwh.dim_customer where is_current union all select 'dim_product', count(*) from dwh.dim_product union all select 'dim_date', count(*) from dwh.dim_date;
